result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/blend.js", "content": "import {
  AnimationClip,
  AnimationMixer,
  Quaternion,
  QuaternionKeyframeTrack,
  Vector3,
} from 'three';

const AXES = {
  x: new Vector3(1, 0, 0),
  y: new Vector3(0, 1, 0),
  z: new Vector3(0, 0, 1),
};

function resolveAxis(axis) {
  if (axis instanceof Vector3) return axis.clone().normalize();
  const key = String(axis).toLowerCase();
  if (!AXES[key]) throw new Error(`Unknown axis: ${axis}`);
  return AXES[key];
}

/**
 * Build an AnimationClip that spins around `axis` at `turnsPerSec` for
 * `durationSec`, with one keyframe per quarter turn.
 */
export function makeSpinClip(name, axis, turnsPerSec, durationSec) {
  const dir = resolveAxis(axis);
  const quarters = Math.max(1, Math.round(turnsPerSec * durationSec * 4));
  const times = [];
  const values = [];

  for (let i = 0; i <= quarters; i++) {
    times.push((i / quarters) * durationSec);
    const q = new Quaternion().setFromAxisAngle(
      dir,
      (i / quarters) * turnsPerSec * durationSec * Math.PI * 2
    );
    values.push(q.x, q.y, q.z, q.w);
  }

  // Track name ".quaternion" binds directly to the mixer root's quaternion.
  const track = new QuaternionKeyframeTrack('.quaternion', times, values);
  return new AnimationClip(name, durationSec, [track]);
}

/**
 * Create a mixer on `root` playing `clipA` and `clipB` simultaneously,
 * blended with weights weightA / (1 - weightA).
 */
export function makeBlendedMixer(root, clipA, clipB, weightA) {
  const wA = Math.min(1, Math.max(0, weightA));
  const wB = 1 - wA;

  const mixer = new AnimationMixer(root);
  const actionA = mixer.clipAction(clipA);
  const actionB = mixer.clipAction(clipB);

  actionA.setEffectiveWeight(wA).play();
  actionB.setEffectiveWeight(wB).play();

  return { mixer, actionA, actionB };
}
"})
