result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/blend.test.js", "content": "import { expect, it } from 'vitest';
import { Object3D, Quaternion, Vector3 } from 'three';
import { makeBlendedMixer, makeSpinClip } from '../src/blend.js';

const Y = new Vector3(0, 1, 0);
const X = new Vector3(1, 0, 0);

function spinAbout(axis, radians) {
  return new Quaternion().setFromAxisAngle(axis, radians);
}

function angleOf(q) {
  return 2 * Math.acos(Math.min(1, Math.abs(q.w)));
}

it('weightA=1: stepping to t=1 yields a quarter turn about Y', () => {
  const root = new THREE_OBJECT();
  const clipY = makeSpinClip('spinY', 'y', 0.25, 1);
  const clipX = makeSpinClip('spinX', 'x', 0.5, 1);

  const { mixer } = makeBlendedMixer(root, clipY, clipX, 1);

  for (let i = 0; i < 10; i++) mixer.update(0.1);

  const expected = spinAbout(Y, Math.PI / 2); // 0.25 turns * 2pi
  expect(root.quaternion.angleTo(expected)).toBeLessThan(1e-3);
});

it('weightA=0: stepping to t=1 yields a half turn about X', () => {
  const root = new THREE_OBJECT();
  const clipY = makeSpinClip('spinY', 'y', 0.25, 1);
  const clipX = makeSpinClip('spinX', 'x', 0.5, 1);

  const { mixer } = makeBlendedMixer(root, clipY, clipX, 0);

  for (let i = 0; i < 10; i++) mixer.update(0.1);

  const expected = spinAbout(X, Math.PI); // 0.5 turns * 2pi
  expect(root.quaternion.angleTo(expected)).toBeLessThan(1e-3);
});

it('weightA=0.5 at t=0.5: normalized quaternion with angle strictly between the pure clips', () => {
  const root = new THREE_OBJECT();
  const clipY = makeSpinClip('spinY', 'y', 0.25, 1);
  const clipX = makeSpinClip('spinX', 'x', 0.5, 1);

  const { mixer } = makeBlendedMixer(root, clipY, clipX, 0.5);
  mixer.update(0.5);

  expect(root.quaternion.length()).toBeCloseTo(1, 5);

  const angle = angleOf(root.quaternion);
  const pureY = angleOf(spinAbout(Y, 0.25 * 0.5 * Math.PI * 2)); // pi/4
  const pureX = angleOf(spinAbout(X, 0.5 * 0.5 * Math.PI * 2)); // pi/2

  expect(angle).toBeGreaterThan(pureY);
  expect(angle).toBeLessThan(pureX);
});
"})
